MODELS=['tabm','bilstm','mlp','gcn','svr_rbf','bai_lstm','transformer','catboost','random_forest','elastic_net']
NAMES=['TabM','BiLSTM','MLP','GCN','SVR-RBF','Bai LSTM','Transformer','CatBoost','Random Forest','Elastic Net']
SHORT=['BiLSTM','MLP','GCN','SVR','Bai','Transf.','CB','RF','EN']
W=['overall','rain','dry_overcast','clear_dry','other']
WL=dict(overall='Overall',rain='Rain',dry_overcast='Overcast',clear_dry='Clear/dry',other='Other')
GROUPS=[('LOCAL_validation','local','Local validation'),('LOCAL_test','local','Local test'),('UK','pooled','UK pooled'),('UK','chilbolton','Chilbolton'),('UK','sparsholt','Sparsholt')]
def esc(x):
 s=str(x)
 for a,b in [('\\',r'\textbackslash{}'),('&',r'\&'),('%',r'\%'),('_',r'\_'),('#',r'\#')]:s=s.replace(a,b)
 return s
def fmt(x,d=4,signed=False):
 if pd.isna(x) or not math.isfinite(float(x)):return '--'
 if abs(x)<.5*10**(-d):x=0.
 return f'{x:+.{d}f}' if signed else f'{x:.{d}f}'

def main():
 ap=argparse.ArgumentParser();ap.add_argument('--package',type=Path,default=ROOT/'最终提交的修改材料/论文图表_20261030_001');a=ap.parse_args()
 out=a.package;src=out/'04_Source_Data/frozen_exports';td=out/'02_Tables_LaTeX';dd=out/'04_Source_Data/table_data';dd.mkdir(exist_ok=True);td.mkdir(exist_ok=True)
 inventory=[];mainfiles=[];suppfiles=[]
 def tabular(headers,rows,spec=None):
  spec=spec or ('l'+'r'*(len(headers)-1))
  body='\\toprule\n'+' & '.join(headers)+r' \\'+'\n\\midrule\n'
  for r in rows:
   if isinstance(r,str):body+=r+'\n'
   else:body+=' & '.join(map(str,r))+r' \\'+'\n'
  return '\\begin{tabular}{'+spec+'}\n'+body+'\\bottomrule\n\\end{tabular}\n'
 def panel(title,headers,rows,spec=None):
  return '\\par\\smallskip\\textbf{'+title+'}\\par\\smallskip\n\\resizebox{\\textwidth}{!}{%\n'+tabular(headers,rows,spec)+'}\n'
 def table(n,name,title,headers,rows,note,inputs,spec=None,extra='',part=None,supp=False):
  visible=n+(f'({part})' if part else '')
  cap='\\caption{'+title+'}\\label{tab:'+name+'}\n'
  t='% Generated by build_tables.py; source files: '+', '.join(inputs)+'\n'
  t+='\\begingroup\n\\renewcommand{\\thetable}{'+visible+'}\n\\begin{table*}[!htbp]\n\\centering\n'+cap
  t+='\\small\\setlength{\\tabcolsep}{4pt}\\renewcommand{\\arraystretch}{1.12}\n'
  t+='\\resizebox{\\textwidth}{!}{%\n'+tabular(headers,rows,spec)+'}\n'+extra
  t+='\\par\\smallskip\n\\begin{minipage}{\\textwidth}\\footnotesize '+note+'\\end{minipage}\n\\end{table*}\n\\endgroup\n'
  fn=name+'.tex';(td/fn).write_text(t,encoding='utf8')
  (suppfiles if supp else mainfiles).append(fn)
  pd.DataFrame([r for r in rows if not isinstance(r,str)],columns=headers).to_csv(dd/(name+'.csv'),index=False,encoding='utf8')
  inventory.append(dict(id=name,number=visible,caption=title,files=['02_Tables_LaTeX/'+fn],inputs=inputs,generator='build_tables.py',note=note))
 # 1. Separate nominal hardware from the current data-analysis cadence.
 rows=[['Beacon frequency','19.13 GHz'],['Satellite longitude / latitude',r'$125.0^{\circ}$E / $0.0^{\circ}$'],['Receiver longitude / latitude',r'$116.3^{\circ}$E / $39.9^{\circ}$N'],['Satellite EIRP (nominal)','13.0 dBW'],['Receive-antenna gain (nominal)','35.0 dBi'],['Feeder loss (nominal)','7.8 dB'],['LNB amplification gain (nominal)','60.0 dB'],['Acquisition module','NI PXIe-5841'],['Original IQ sampling specification','4 kHz; 4000 samples per 1-s snapshot'],['Current power-record interval','100 ms'],['Second-scale aggregation','1 s; at least 9 valid records per second'],['Hourly aggregation','1 h; at least 34,200 valid 100-ms records'],['Clear-sky reference (training only)',r'$-76.193629$ dBm; median of 1127 clear/dry hours']]
 table('1','Table01_Measurement_Configuration','Measurement configuration and analysis resolution.', ['Parameter','Value'],rows,'Nominal hardware and IQ settings follow the original manuscript, p.~3, Table~I and Section~II.B. The current power-processing resolution follows the frozen dataset construction. IQ sampling rate and power-record cadence are different quantities. The archived table\'s ``1 Hz'' label is not used as the IQ sample rate.', ['methods/00_English_2026_TVT.pdf','methods/14_README.md'],spec='ll')
