 allcmp=[]
 def comparison(frame,scope,ks,weathers):
  rrows=[];drows=[]
  for w in weathers:
   for k in ks:
    g=frame[(frame.weather==w)&(frame.k==k)].set_index('model');t=g.loc['tabm'];rr=[WL[w],str(k),fmt(t.rmse_db)];dr=[WL[w],str(k),fmt(t.r2)]
    for m in MODELS[1:]:
     b=g.loc[m];pct=100*(b.rmse_db-t.rmse_db)/b.rmse_db;delta=t.r2-b.r2
     rr.append(fmt(pct,2,True));dr.append(fmt(delta,4,True));allcmp.append(dict(scope=scope,weather=w,k=k,n=int(t.n),baseline=m,tabm_rmse=t.rmse_db,baseline_rmse=b.rmse_db,rmse_reduction_percent=pct,tabm_r2=t.r2,baseline_r2=b.r2,delta_r2=delta))
    rrows.append(rr);drows.append(dr)
  return rrows,drows
