 table('4','Table04_Local_Ten_Model_Comparison',r'Local test comparison with TabM at representative retained feature counts. Upper panel: RMSE reduction (\%); lower panel: absolute $R^2$ difference.', ['Weather','$k$',r'TabM RMSE']+SHORT,rr,note,['frozen_exports/local_metrics.csv'],extra=panel('(b) Absolute $R^2$ difference',['Weather','$k$',r'TabM $R^2$']+SHORT,dr))
